#include <stdio.h>

int main(void) {
    int values[] = { 3, 8, 5, 10 };
    size_t count = sizeof values / sizeof values[0];
    long sum = 0;
    size_t even_count = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += values[i];
        if (values[i] % 2 == 0) ++even_count;
    }
    printf("sum=%ld even=%zu\n", sum, even_count);
    return 0;
}

#include <stddef.h>

size_t find_value(const int values[], size_t count, int target) {
    for (size_t i = 0; i < count; ++i) {
        if (values[i] == target) return i;
    }
    return count; /* not found sentinel, documented by this API */
}
